select *, last_value(age, true) over w_ordered as last_known_age, avg(age) over (partition by city order by signup_date, id rows between 3 preceding and current row) as age_avg_3, ntile(3) over w_grp as age_bucket from customers window w_ordered as (partition by country, city order by credit_limit, id rows between unbounded preceding and current row), w_grp as (partition by country, city order by age, id);
